const asyncHooks = require("node:async_hooks");
const { Console } = require("node:console");
const diagnostics = require("node:diagnostics_channel");
const { EventEmitter } = require("node:events");
const os = require("node:os");
const { Writable } = require("node:stream");
const traceEvents = require("node:trace_events");
const v8 = require("node:v8");
const childProcess = require("node:child_process");

function attempt(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

async function attemptAsync(operation) {
  try {
    await operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function waitForSuccess(child) {
  return new Promise((resolve, reject) => {
    child.once("error", reject);
    child.once("exit", (code, signal) => {
      if (code === 0) resolve();
      else reject(new Error(`child failed: code=${code} signal=${signal}`));
    });
  });
}

let existingSignalCount = 0;
let failedSignalCount = 0;
const existingSignalListener = () => existingSignalCount++;
const failedSignalListener = () => failedSignalCount++;
const denoOverlayChild = `${__dirname}/fork_env_child.cjs`;

exports.run = async function probeDenyOnlyRows(root) {
  const results = {
    cwdRead: attempt(() => Deno.cwd()),
    cwdWrite: attempt(() => Deno.chdir(root.cwd)),
    umaskRead: attempt(() => process.umask()),
    umaskWrite: attempt(() => process.umask(root.umask)),
    identity: typeof process.seteuid === "function"
      ? attempt(() => process.seteuid(root.identity))
      : "UNAVAILABLE",
    title: attempt(() => { process.title = root.title; }),
    priority: attempt(() => os.setPriority(process.pid, root.priority)),
    envSet: attempt(() => Deno.env.set("ODEN_STAGE_B_PROBE", "1")),
    envDelete: attempt(() => Deno.env.delete("ODEN_STAGE_B_PROBE")),
    envFile: attempt(() => process.loadEnvFile("probe.env")),
    signalBindExisting: attempt(() =>
      Deno.addSignalListener("SIGUSR2", existingSignalListener)
    ),
    signalBindFailed: attempt(() =>
      Deno.addSignalListener("SIGHUP", failedSignalListener)
    ),
    signalSelf: attempt(() => process.kill(process.pid, 0)),
    signalInspector: attempt(() => process.kill(process.pid, "SIGUSR1")),
    report: attempt(() => process.report.getReport()),
    activeHandles: attempt(() => process._getActiveHandles()),
    activeResources: attempt(() => process.getActiveResourcesInfo()),
    asyncHooks: attempt(() => asyncHooks.createHook({ init() {} })),
    asyncHookLaunder: attempt(() => root.rootHook.enable()),
    asyncHookDisableLaunder: attempt(() => root.rootHook.disable()),
    asyncHookReflectMutation: attempt(() => {
      for (const key of Reflect.ownKeys(root.rootHook)) {
        root.rootHook[key] = () => {};
      }
    }),
    diagnostics: attempt(() => diagnostics.channel("oden-stage-b").subscribe(() => {})),
    diagnosticsLaunder: attempt(() => root.rootChannel.subscribe(() => {})),
    diagnosticsHasSubscribers: attempt(() => diagnostics.hasSubscribers("oden-stage-b")),
    diagnosticsPassedHasSubscribers: attempt(() => root.rootChannel.hasSubscribers),
    diagnosticsPublishLaunder: attempt(() => root.rootChannel.publish({ package: true })),
    diagnosticsRunStoresLaunder: attempt(() =>
      root.rootChannel.runStores({ package: true }, () => {})
    ),
    diagnosticsBackingRead: attempt(() => root.rootChannel._subscribers),
    diagnosticsBackingWrite: attempt(() => {
      root.rootChannel._subscribers = [() => {}];
      root.rootChannel._stores = new Map();
    }),
    internalDiagnosticsPublish: attempt(() => {
      const sink = new Writable({
        write(_chunk, _encoding, callback) {
          callback();
        },
      });
      new Console(sink).log("trusted internal diagnostics publisher");
    }),
    processBinding: attempt(() => process.binding("async_wrap")),
    bindingPassedRead: attempt(() => root.rootBinding.async_hook_fields),
    bindingPassedNestedRead: attempt(() => root.rootBindingFields[0]),
    bindingPassedNestedWrite: attempt(() => { root.rootBindingFields[0] = 999999; }),
    bindingDescriptorPassedRead: attempt(() => root.rootBindingDescriptorValue[0]),
    bindingDescriptorPassedWrite: attempt(() => {
      root.rootBindingDescriptorValue[0] = 999999;
    }),
    bindingPassedCall: attempt(() => root.rootBinding.newAsyncId()),
    captureCallback: attempt(() => process.setUncaughtExceptionCaptureCallback(() => {})),
    captureCallbackRead: attempt(() => process.hasUncaughtExceptionCaptureCallback()),
    fatalExceptionRead: attempt(() => process._fatalException),
    fatalException: attempt(() => process._fatalException(new Error("probe"))),
    fatalExceptionPassed: attempt(() => root.rootFatalException(new Error("probe"))),
    childRef: attempt(() => root.rootChild.ref()),
    spawnSyncDefaultCleanup: attempt(() => {
      const result = childProcess.spawnSync(
        "/bin/sh",
        [
          "-c",
          'test "$ODEN_CHILD_SAFE_SENTINEL" = "safe" && test -z "$ODEN_CAPSEC_CHILD_SENTINEL"',
        ],
        { timeout: 1000 },
      );
      if (result.error || result.status !== 0) throw result.error || result;
    }),
    spawnSyncExplicitEnv: attempt(() => {
      const result = childProcess.spawnSync(
        "/bin/sh",
        [
          "-c",
          'test "$ONLY" = "yes" && test -z "$ODEN_CHILD_SAFE_SENTINEL"',
        ],
        { env: { ONLY: "yes" }, timeout: 1000 },
      );
      if (result.error || result.status !== 0) throw result.error || result;
    }),
    spawnSyncFalsyEnv: attempt(() => {
      for (const env of [null, false, 0, ""]) {
        const result = childProcess.spawnSync(
          "/bin/sh",
          [
            "-c",
            'test "$ODEN_CHILD_SAFE_SENTINEL" = "safe" && test -z "$ODEN_CAPSEC_CHILD_SENTINEL"',
          ],
          { env, timeout: 1000 },
        );
        if (result.error || result.status !== 0) throw result.error || result;
      }
    }),
    spawnSyncDenoOverlay: attempt(() => {
      const result = childProcess.spawnSync(
        Deno.execPath(),
        ["--no-warnings", denoOverlayChild],
        { timeout: 1000 },
      );
      if (result.error || result.status !== 0) throw result.error || result;
    }),
    spawnSyncCustomSignal: attempt(() =>
      childProcess.spawnSync("/bin/sh", ["-c", ""], {
        timeout: 1000,
        killSignal: "SIGUSR1",
      })
    ),
    processExceptionOn: attempt(() => process.on("uncaughtException", () => {})),
    processExceptionOnce: attempt(() => process.once("uncaughtException", () => {})),
    processExceptionPrepend: attempt(() =>
      process.prependListener("uncaughtException", () => {})
    ),
    processExceptionRemove: attempt(() =>
      process.removeListener("uncaughtException", root.rootExceptionListener)
    ),
    processExceptionRemoveAll: attempt(() =>
      process.removeAllListeners("uncaughtException")
    ),
    processExceptionEmit: attempt(() =>
      process.emit("uncaughtException", new Error("probe"))
    ),
    processExceptionObserve: attempt(() => process.listeners("uncaughtException")),
    processExceptionBorrowedOn: attempt(() =>
      EventEmitter.prototype.on.call(process, "uncaughtException", () => {})
    ),
    processExceptionEventsRead: attempt(() => process._events.uncaughtException),
    processExceptionEventsWrite: attempt(() => {
      process._events.uncaughtException = () => {};
    }),
    processExceptionEventsOwnKeys: attempt(() => Reflect.ownKeys(process._events)),
    processExceptionEventsDescriptor: attempt(() =>
      Object.getOwnPropertyDescriptor(process._events, "uncaughtException")
    ),
    processEventsReplace: attempt(() => { process._events = Object.create(null); }),
    processMetaOn: attempt(() => process.on("newListener", () => {})),
    processMetaEmit: attempt(() => process.emit("newListener", "uncaughtException", () => {})),
    processMetaEventsRead: attempt(() => process._events.newListener),
    processMetaEventsDescriptor: attempt(() =>
      Object.getOwnPropertyDescriptor(process._events, "newListener")
    ),
    processMetaBorrowedOn: attempt(() =>
      EventEmitter.prototype.on.call(process, "newListener", () => {})
    ),
    processOrdinaryEvent: attempt(() => {
      const listener = () => {};
      process.on("oden-ordinary-event", listener);
      process.removeListener("oden-ordinary-event", listener);
    }),
    processSignalOn: attempt(() => process.on("SIGUSR2", () => {})),
    processSignalPrepend: attempt(() =>
      process.prependListener("SIGUSR2", () => {})
    ),
    processSignalRemove: attempt(() =>
      process.removeListener("SIGUSR2", root.rootProcessSignalListener)
    ),
    processSignalRemoveAll: attempt(() => process.removeAllListeners("SIGUSR2")),
    processSignalEmit: attempt(() => process.emit("SIGUSR2")),
    processSignalObserve: attempt(() => process.listeners("SIGUSR2")),
    processSignalEventsRead: attempt(() => process._events.SIGUSR2),
    processSignalEventsDescriptor: attempt(() =>
      Object.getOwnPropertyDescriptor(process._events, "SIGUSR2")
    ),
    processSignalEventsWrite: attempt(() => { process._events.SIGUSR2 = () => {}; }),
    ttyResize: process.stdout.isTTY === true
      ? attempt(() => process.stdout.on("resize", root.rootResizeListener))
      : "UNAVAILABLE",
    traceEvents: attempt(() => traceEvents.createTracing({ categories: ["node"] }).enable()),
    traceDisableLaunder: attempt(() => root.rootTracing.disable()),
    traceReflectMutation: attempt(() => {
      for (const key of Reflect.ownKeys(root.rootTracing)) {
        root.rootTracing[key] = false;
      }
    }),
    gcProfilerReflectMutation: attempt(() => {
      for (const key of Reflect.ownKeys(root.rootGcProfiler)) {
        root.rootGcProfiler[key] = null;
      }
    }),
    gcProfilerStopLaunder: attempt(() => root.rootGcProfiler.stop()),
    gcProfilerDisposeLaunder: attempt(() =>
      root.rootGcProfilerDispose[Symbol.dispose]()
    ),
    inspectorConsoleGet: attempt(() => root.inspectorConsole.log),
    inspectorConsoleDescriptor: attempt(() =>
      Object.getOwnPropertyDescriptor(root.inspectorConsole, "log")
    ),
    inspectorConsoleOwnKeys: attempt(() => Reflect.ownKeys(root.inspectorConsole)),
    inspectorConsoleSet: attempt(() => { root.inspectorConsole.log = () => {}; }),
    inspectorConsoleDefine: attempt(() =>
      Object.defineProperty(root.inspectorConsole, "log", { value() {} })
    ),
    inspectorConsoleDelete: attempt(() => { delete root.inspectorConsole.log; }),
    inspectorConsolePrototype: attempt(() => Object.getPrototypeOf(root.inspectorConsole)),
    v8Heap: attempt(() => v8.getHeapStatistics()),
    v8Flags: attempt(() => v8.setFlagsFromString("")),
    v8Snapshot: attempt(() => v8.getHeapSnapshot()),
    abortCore: attempt(() => process.abort()),
  };
  results.spawnAsyncDefaultEnv = await attemptAsync(() =>
    waitForSuccess(childProcess.spawn(
      "/bin/sh",
      [
        "-c",
        'test "$ODEN_CHILD_SAFE_SENTINEL" = "safe" && test -z "$ODEN_CAPSEC_CHILD_SENTINEL"',
      ],
      { stdio: "ignore" },
    ))
  );
  results.spawnAsyncExplicitEnv = await attemptAsync(() =>
    waitForSuccess(childProcess.spawn(
      "/bin/sh",
      [
        "-c",
        'test "$ONLY" = "yes" && test -z "$ODEN_CHILD_SAFE_SENTINEL"',
      ],
      { env: { ONLY: "yes" }, stdio: "ignore" },
    ))
  );
  results.spawnAsyncDenoOverlay = await attemptAsync(() =>
    waitForSuccess(childProcess.spawn(
      Deno.execPath(),
      ["--no-warnings", denoOverlayChild],
      { stdio: "ignore" },
    ))
  );
  results.forkInheritedEnv = await attemptAsync(() =>
    waitForSuccess(childProcess.fork(
      `${__dirname}/fork_env_child.cjs`,
      [],
      { execArgv: ["--no-warnings"], silent: true },
    ))
  );
  await Promise.resolve();
  results.promiseReport = attempt(() => process.report.getReport());
  return results;
};

exports.signalCounts = () => ({
  existing: existingSignalCount,
  failed: failedSignalCount,
});
